INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000001','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel numéro d''urgence permet d''appeler le SAMU ?','Le 15 est le numéro du SAMU (Service d''Aide Médicale Urgente). Il s''appelle en cas d''urgence médicale grave (malaise, accident, blessure...).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000002','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel numéro d''urgence permet d''appeler les pompiers ?','Le 18 est le numéro des pompiers. Ils interviennent pour les incendies, les accidents, les secours d''urgence et les catastrophes.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000003','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Qu''est-ce qu''un numéro d''urgence ?','Un numéro d''urgence est un numéro gratuit que l''on peut appeler en cas de situation grave : 15 (SAMU), 17 (Police), 18 (Pompiers), 112 (numéro européen).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000004','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Après avoir obtenu le permis de conduire, que faut-il faire pour pouvoir conduire sa voiture ?','Après l''obtention du permis, il faut faire immatriculer son véhicule (carte grise) et le faire assurer obligatoirement (assurance auto au minimum responsabilité civile).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000005','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','À quelles conditions un mariage est-il reconnu juridiquement en France ?','Un mariage est juridiquement reconnu en France uniquement s''il est célébré par un officier d''état civil (le maire ou son adjoint) à la mairie. Les mariages religieux n''ont pas de valeur civile.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000006','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Quand faut-il déclarer son enfant au service d''état civil de la mairie ?','La déclaration de naissance doit être faite dans les 5 jours suivant la naissance (jour de l''accouchement non compris), à la mairie du lieu de naissance.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000007','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Le travail non déclaré est :','Le travail non déclaré (travail au noir) est illégal. Il prive le travailleur de droits sociaux (chômage, retraite, sécurité sociale) et expose employeur et salarié à des sanctions.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000008','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Que doit faire un employeur pour fixer un salaire ?','L''employeur doit respecter le SMIC (salaire minimum légal) et la convention collective applicable. Le salaire ne peut être inférieur au SMIC.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000009','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Qu''est-ce que le SMIC ?','Le SMIC (Salaire Minimum Interprofessionnel de Croissance) est le salaire horaire minimum légal en dessous duquel un employeur ne peut pas payer un salarié.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000000a','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Quelle est la première démarche à réaliser pour chercher un emploi ?','La première démarche est de s''inscrire à France Travail (anciennement Pôle Emploi). Cela permet de bénéficier d''un accompagnement et éventuellement d''indemnités de chômage.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000000b','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quelle est la durée légale du temps de travail par semaine ?','La durée légale du temps de travail en France est de 35 heures par semaine pour un temps plein, depuis les lois Aubry de 2000.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000000c','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Qui est aidé par France Travail ?','France Travail (ex-Pôle Emploi) accompagne les demandeurs d''emploi : inscription, recherche d''emploi, indemnités, formation. Les entreprises peuvent également être aidées dans leurs recrutements.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000000d','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Une personne étrangère en situation régulière peut créer son entreprise :','Oui. Toute personne étrangère en situation régulière peut créer une entreprise en France, dans les mêmes conditions qu''un citoyen français.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000000e','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','MISE_SITUATION','Une femme peut-elle créer son entreprise ?','Oui. L''égalité hommes-femmes est un principe constitutionnel. Une femme peut créer son entreprise dans les mêmes conditions qu''un homme, sans autorisation particulière.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000000f','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','À partir de quel âge un mineur peut-il travailler ?','Un mineur peut travailler à partir de 16 ans (avec autorisation parentale). Dès 14 ans, il peut faire des petits travaux pendant les vacances scolaires sous conditions strictes.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000010','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Auprès de quel organisme faut-il demander le remboursement des frais de santé ?','Les remboursements de frais de santé sont assurés par l''Assurance Maladie (CPAM - Caisse Primaire d''Assurance Maladie), qui fait partie de la Sécurité sociale.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000011','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Concernant l''accès aux soins, quelle proposition est correcte ?','L''accès aux soins est un droit en France. Le système de Sécurité sociale permet à toute personne résidant en France de bénéficier d''une prise en charge des frais de santé.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000012','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','MISE_SITUATION','En cas de problème de santé non urgent, à qui faut-il s''adresser en premier ?','En cas de problème de santé non urgent, il faut consulter son médecin traitant. Il est le premier contact dans le parcours de soins et oriente si nécessaire vers un spécialiste.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000013','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Quel est le rôle du médecin traitant ?','Le médecin traitant est le premier contact pour les questions de santé. Il coordonne le parcours de soins, oriente vers les spécialistes et permet un meilleur remboursement par la Sécurité sociale.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000014','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Dans quelles situations doit-on se rendre aux urgences de l''hôpital ?','Les urgences sont réservées aux situations graves et imminentes : accident, malaise grave, hémorragie, douleur intense, perte de conscience. Pour les soins non urgents, voir un médecin traitant.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000015','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Quel est l''objectif des vaccinations obligatoires ?','Les vaccinations obligatoires protègent l''enfant contre certaines maladies graves et évitent leur propagation. En France, 11 vaccins sont obligatoires pour les enfants nés depuis 2018.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000016','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','À quoi sert la carte Vitale ?','La carte Vitale est la carte d''assuré social. Elle permet de bénéficier des remboursements de l''Assurance Maladie en attestant des droits à la Sécurité sociale.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000017','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','À quoi sert une mutuelle santé ?','La mutuelle (complémentaire santé) rembourse la partie des frais de santé qui n''est pas prise en charge par la Sécurité sociale. Elle est facultative mais fortement recommandée.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000018','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Jusqu''à quel âge l''école est-elle obligatoire ?','L''instruction est obligatoire de 3 à 16 ans en France (depuis 2019, l''âge d''entrée a été abaissé à 3 ans, contre 6 ans auparavant).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-000000000019','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','L''autorité parentale prévoit l''obligation :','L''autorité parentale impose aux parents de protéger, éduquer, instruire et assurer l''entretien de leurs enfants jusqu''à leur majorité (18 ans).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000001a','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Pour qui l''école est-elle obligatoire ?','L''instruction est obligatoire pour tous les enfants de 3 à 16 ans résidant en France, qu''ils soient français ou étrangers, en situation régulière ou non.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000001b','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel diplôme obtient-on à la fin du lycée ?','À la fin du lycée, les élèves passent le baccalauréat (le "bac"), diplôme qui sanctionne la fin des études secondaires et permet de poursuivre dans l''enseignement supérieur.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000001c','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Dans quels établissements scolaires vont les élèves après l''école élémentaire ?','Après l''école élémentaire (jusqu''au CM2), les élèves vont au collège (6e à 3e), puis au lycée (2de, 1re, terminale).','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000001d','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Pour qui l''école est-elle obligatoire ?','L''école est obligatoire pour tous les enfants résidant sur le territoire français, quelle que soit leur nationalité ou la situation administrative de leurs parents.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000001e','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Un enfant inscrit à l''école :','Un enfant inscrit à l''école doit la fréquenter de manière régulière. L''assiduité est obligatoire. Les absences injustifiées peuvent être sanctionnées.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000000-0000-0000-0000-00000000001f','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Les enfants qui ne parlent pas français :','Les enfants qui ne parlent pas français sont accueillis à l''école dans des dispositifs adaptés (UPE2A - Unité Pédagogique pour Élèves Allophones Arrivants) pour apprendre le français et suivre une scolarité normale.','true','2026-05-27 17:40:29.759953+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000001','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel numéro d''urgence permet d''appeler le SAMU (urgences médicales) ?','Le 15 est le numéro du SAMU (service d''aide médicale urgente). Il est gratuit et accessible 24h/24.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000002','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quel numéro d''urgence permet d''appeler les pompiers en France ?','Le 18 est le numéro des pompiers en France. Il est gratuit et accessible 24h/24.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000003','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Que désigne un numéro d''urgence en France ?','Un numéro d''urgence est un numéro court, gratuit, accessible 24h/24, qui permet d''appeler les services de secours (police 17, pompiers 18, SAMU 15, urgence européenne 112).','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000004','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Après avoir obtenu le permis de conduire, que faut-il faire pour conduire légalement ?','Il faut s''assurer (assurance auto obligatoire), avoir le certificat d''immatriculation (carte grise) du véhicule, respecter le Code de la route, et avoir un contrôle technique à jour.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000005','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','À quelles conditions un mariage civil est-il valable en France ?','Le mariage civil est valable si : les deux personnes sont majeures, libres (non mariées ailleurs), consentantes, sans lien de parenté proche, et que le mariage est célébré par un officier d''état civil (maire/adjoint).','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000006','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Quand doit-on déclarer la naissance d''un enfant à l''état civil ?','La déclaration de naissance doit être faite dans les 5 jours qui suivent la naissance (ou 8 jours pour l''outre-mer), à la mairie du lieu de naissance, par le père ou un proche.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000007','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Que désigne le ''travail non déclaré'' en droit français ?','Le travail non déclaré (travail dissimulé, travail au noir) est l''exercice d''une activité rémunérée sans déclaration aux organismes sociaux et fiscaux. C''est un délit puni par la loi.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000008','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Comment un employeur doit-il fixer le salaire d''un salarié ?','Le salaire doit respecter le SMIC (minimum légal), la convention collective applicable (qui peut fixer un minimum supérieur), et le contrat de travail. Il doit être versé mensuellement.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000009','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Que désigne le SMIC en France ?','Le SMIC (Salaire minimum interprofessionnel de croissance) est le salaire horaire minimum légal en France. Il est revalorisé chaque année (au 1er janvier) en fonction de l''inflation.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000000a','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Quelle est la première démarche pour rechercher un emploi en France ?','S''inscrire à France Travail (ex Pôle emploi) permet de bénéficier d''un accompagnement, d''offres d''emploi, et éventuellement d''une indemnisation chômage si on a déjà cotisé.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000000b','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','CONNAISSANCE','Quelle est la durée légale du travail hebdomadaire en France ?','La durée légale du travail est de 35 heures par semaine pour un salarié à temps plein. Au-delà, ce sont des heures supplémentaires (majorées).','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000000c','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Qui est accompagné par France Travail (ex Pôle emploi) ?','France Travail accompagne les personnes en recherche d''emploi : chômeurs (avec ou sans indemnités), salariés cherchant à changer de poste, jeunes diplômés, personnes en reconversion.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000000d','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','MISE_SITUATION','Une personne étrangère en situation régulière peut-elle créer son entreprise en France ?','Oui. Une personne étrangère en situation régulière peut créer son entreprise en France. Certains titres de séjour permettent expressément l''exercice d''une activité professionnelle.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000000e','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','MISE_SITUATION','Une femme peut-elle créer son entreprise en France ?','Oui. Les femmes ont exactement les mêmes droits que les hommes pour créer une entreprise. Il n''existe aucune restriction liée au sexe. Diverses aides existent même pour encourager l''entrepreneuriat féminin.','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-00000000000f','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','À quel âge un mineur peut-il commencer à travailler en France ?','Un mineur peut travailler à partir de 14 ans pour des travaux légers et adaptés, avec autorisation parentale. À partir de 16 ans, il peut être apprenti ou salarié ordinaire (avec encore des restrictions).','true','2026-05-27 17:40:30.069886+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000010','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Auprès de quel organisme demande-t-on le remboursement de ses frais de santé ?','C''est l''Assurance Maladie (Caisse primaire d''assurance maladie - CPAM) qui rembourse les frais de santé. La carte Vitale facilite ces remboursements.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000011','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Que peut-on dire de l''accès aux soins en France ?','L''accès aux soins est un droit garanti. Toute personne résidant régulièrement en France a droit à la protection maladie universelle (PUMA), qui rembourse une partie des frais.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000012','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CSP','MISE_SITUATION','En cas de problème de santé non urgent, vers qui se diriger en premier ?','Le médecin traitant (médecin généraliste) est le premier interlocuteur pour les problèmes de santé non urgents. Il oriente vers un spécialiste si nécessaire (parcours de soins coordonné).','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
INSERT INTO questions (id, module, theme_id, passage_id, media_id, difficulty, question_type, statement, explanation, is_active, created_at, updated_at, status, tcf_sub_theme, audio_mode, competence_code) VALUES ('f5000001-0000-0000-0000-000000000013','CIVIQUE','11111111-0000-0000-0000-000000000005',NULL,NULL,'CR','CONNAISSANCE','Quel est le rôle d''un médecin traitant en France ?','Le médecin traitant assure le suivi médical de premier recours, oriente vers les spécialistes si nécessaire, coordonne les soins. Le déclarer permet un meilleur remboursement.','true','2026-05-27 17:40:30.076195+02',NULL,'ACTIVE',NULL,NULL,NULL);
